1	/**
2	 * Pi Verifier Agent — verifier-side extension.
3	 *
4	 * Loaded into the *child* Pi instance that runs inside the tmux window the
5	 * launcher created. The default-export factory is invoked by Pi at startup
6	 * with `pi -e ./apps/verifier/verifier.ts --child --builder-session <sid>
7	 * --agent <path> --system-prompt <rendered>`.
8	 *
9	 * Responsibilities:
10	 *
11	 *   1. Replace the input editor with a colored full-width status bar
12	 *      (`VerifierStatusBar`) that swallows typing but preserves operational
13	 *      shortcuts (Esc, Ctrl+D, model switch). Defense-in-depth `pi.on("input")`
14	 *      blocks any non-extension-source input that slips through.
15	 *
16	 *   2. Connect over the unix domain socket the builder bound at
17	 *      `/tmp/pi-verifier/<sid>.sock`. Send `hello`, await `hello_ack`, then
18	 *      stream `event` envelopes (start / stop / error) back from the builder.
19	 *
20	 *   3. Drive the local verifier agent: on every `event { name: "stop" }`,
21	 *      template `.pi/verifier/prompts/verify_on_stop.md` and inject it via
22	 *      `pi.sendUserMessage(...)` (extension-source — passes our input lock).
23	 *
24	 *   4. Expose the `verifier_prompt` tool — the only thing the local agent
25	 *      can use to push corrective feedback back to the builder. It writes a
26	 *      `prompt` envelope and awaits the matching `prompt_ack` (60s timeout).
27	 *
28	 *   5. Enforce the script-only bash policy via `pi.on("tool_call")`. Any
29	 *      `bash` invocation that isn't `<runner> <allowed_script> ...` is
30	 *      blocked with a structured teaching message — the agent reads the
31	 *      block reason and self-corrects on the next step.
32	 *
33	 *   6. On the verifier's own `agent_end`, parse the last assistant message's
34	 *      `## Report` block and ship it back to the builder as a `report`
35	 *      envelope. Update the status bar phase based on STATUS line.
36	 *
37	 *   7. Liveness: 10s ping interval; 2 missed pongs → exit cleanly so the
38	 *      tmux window goes away when the parent dies.
39	 *
40	 * NOT this file's job:
41	 *   - Templating the system prompt (the launcher does that before spawn).
42	 *   - Spawning anything (we're the spawnee).
43	 *   - Reading the builder's session JSONL (the persona body tells the agent
44	 *     to do that via the `read` tool — the extension only carries the
45	 *     transport).
46	 */
47	
48	import type {
49	  AgentEndEvent,
50	  ExtensionAPI,
51	  ExtensionContext,
52	  InputEvent,
53	  InputEventResult,
54	  SessionShutdownEvent,
55	  SessionStartEvent,
56	  ToolCallEvent,
57	  ToolCallEventResult,
58	} from "@mariozechner/pi-coding-agent";
59	import { CustomEditor } from "@mariozechner/pi-coding-agent";
60	import { Text, truncateToWidth, visibleWidth } from "@mariozechner/pi-tui";
61	import { Type } from "typebox";
62	import * as crypto from "node:crypto";
63	import { readFileSync } from "node:fs";
64	import * as net from "node:net";
65	import * as path from "node:path";
66	
67	import { loadDotEnv } from "./_shared/env.js";
68	import { parseVerifierPersona, templateBody, type BashPolicy } from "./_shared/frontmatter.js";
69	import {
70	  assertDirection,
71	  encodeEnvelope,
72	  readEnvelopes,
73	  type Confidence,
74	  type Envelope,
75	  type Event as BuilderEvent,
76	  type Hello,
77	  type Ping,
78	  type Pong,
79	  type Prompt,
80	  type PromptAck,
81	  type Report,
82	} from "./_shared/ipc.js";
83	import { resolveSocketPath } from "./_shared/socket-path.js";
84	
85	// ─── Module state ────────────────────────────────────────────────────────────
86	
87	type Phase =
88	  | "connecting"
89	  | "connected"
90	  | "verifying"
91	  | "verified"
92	  | "failed"
93	  | "unsure"
94	  | "error"
95	  | "disconnected";
96	
97	interface ParsedReport {
98	  status: "verified" | "failed" | "unsure";
99	  /**
100	   * Confidence ladder grade (highest → lowest):
101	   *   PERFECT  — every claim verified, zero unverifiable, zero feedback   (green)
102	   *   VERIFIED — all checked passed; minor non-blocking gaps allowed       (green)
103	   *   PARTIAL  — no failures but significant unverifiable gaps              (orange)
104	   *   UNSURE   — couldn't verify enough to judge; escalating                (orange)
105	   *   FAILED   — at least one claim failed; verifier_prompt called          (red)
106	   * Defaults to a status-derived value if the agent omits the CONFIDENCE: line.
107	   */
108	  confidence: Confidence;
109	  summary: string;
110	  sections: Record<string, string>;
111	}
112	
113	interface VerifierState {
114	  phase: Phase;
115	  builderSessionId: string;
116	  socketPath: string;
117	  parentConn: net.Socket | null;
118	  agentPath: string;
119	  /**
120	   * Persona file name (basename of agentPath, no `.md`, UPPERCASED). Rendered
121	   * as the left segment of the status bar so it's obvious WHICH persona is
122	   * driving this verifier — e.g. `VERIFIER` (generic) vs `VERIFY_SQLITE`
123	   * (SQLite specialization). Empty string until session_start populates it.
124	   */
125	  personaName: string;
126	  bashPolicy: BashPolicy | null;
127	  maxLoops: number;
128	  currentTurnIndex: number;
129	  /** Last error detail surfaced from a builder `event { name: "error" }`. */
130	  errorDetail: string;
131	  /** ms epoch of last inbound traffic — drives "last ack <n>ms ago" footer. */
132	  lastAckTimestamp: number;
133	  pingInterval: NodeJS.Timeout | null;
134	  pendingPongs: number;
135	  pendingPromptAcks: Map<string, (ack: PromptAck) => void>;
136	  /** True if `verifier_prompt` was called during the current verification cycle. */
137	  promptedThisCycle: boolean;
138	  /**
139	   * Confidence grade from the most recent Report. Drives the status-bar
140	   * background color (green / orange / red). `null` means we haven't received
141	   * a Report yet (idle, connecting, or mid-verifying on the first turn).
142	   */
143	  confidence: Confidence | null;
144	  /** Reference to the live UI ctx so the status bar can re-render on phase changes. */
145	  uiCtx: ExtensionContext | null;
146	  /** Set once the `connecting` → `connected` transition has been observed. */
147	  helloAcked: boolean;
148	  /** Suppress cleanup re-entry on shutdown. */
149	  shuttingDown: boolean;
150	}
151	
152	const state: VerifierState = {
153	  phase: "connecting",
154	  builderSessionId: "",
155	  socketPath: "",
156	  parentConn: null,
157	  agentPath: "",
158	  personaName: "",
159	  bashPolicy: null,
160	  maxLoops: 3,
161	  currentTurnIndex: 0,
162	  errorDetail: "",
163	  lastAckTimestamp: 0,
164	  pingInterval: null,
165	  pendingPongs: 0,
166	  pendingPromptAcks: new Map(),
167	  promptedThisCycle: false,
168	  confidence: null,
169	  uiCtx: null,
170	  helloAcked: false,
171	  shuttingDown: false,
172	};
173	
174	// ─── Status-bar helpers (copied verbatim from full-bar-editor.ts) ────────────
175	//
176	// These two helpers implement ASCII-safe truncation + width padding for a
177	// three-segment status bar. Copied verbatim from
178	// `ai_docs/pi/hide-ui-bar/full-bar-editor.ts`. Do not modify.
179	
180	function truncateAscii(text: string, width: number): string {
181	  if (width <= 0) return "";
182	  if (text.length <= width) return text;
183	  if (width <= 1) return text.slice(0, width);
184	  return text.slice(0, width - 1) + "…";
185	}
186	
187	function fullWidthAsciiBar(width: number, left: string, center: string, right: string): string {
188	  if (width <= 0) return "";
189	
190	  // Keep this ASCII/simple-width for reliability. Apply ANSI styling only after
191	  // the raw line has been padded to exactly `width` cells.
192	  const minGap = " ";
193	  const fixedRight = right;
194	  const fixedCenter = center;
195	
196	  let availableForLeft = width - fixedCenter.length - fixedRight.length - minGap.length * 2;
197	  if (availableForLeft < 0) availableForLeft = 0;
198	
199	  const safeLeft = truncateAscii(left, availableForLeft);
200	  let raw = safeLeft + minGap + fixedCenter + minGap + fixedRight;
201	
202	  if (raw.length > width) raw = truncateAscii(raw, width);
203	  if (raw.length < width) raw = raw + " ".repeat(width - raw.length);
204	
205	  return raw;
206	}
207	
208	// ─── Phase formatting ────────────────────────────────────────────────────────
209	
210	function formatPhase(phase: Phase): string {
211	  switch (phase) {
212	    case "connecting":
213	      return "◌ connecting...";
214	    case "connected":
215	      return "● connected to builder";
216	    case "verifying":
217	      return "… verifying...";
218	    case "verified":
219	      return "✓ verified";
220	    case "failed":
221	      return state.promptedThisCycle
222	        ? "✗ failed · prompted builder"
223	        : "✗ failed";
224	    case "unsure":
225	      return "⚠ unsure";
226	    case "error":
227	      return `⚠ builder error: ${truncateAscii(state.errorDetail || "(no detail)", 40)}`;
228	    case "disconnected":
229	      return "✗ socket dropped — exiting in 5s";
230	  }
231	}
232	
233	function ageMs(timestamp: number): number {
234	  if (!timestamp) return 0;
235	  return Math.max(0, Date.now() - timestamp);
236	}
237	
238	function shortSid(sid: string): string {
239	  return sid.length <= 8 ? sid : `${sid.slice(0, 8)}...`;
240	}
241	
242	/**
243	 * Pick a background color (ANSI 256) for the verifier status bar based on the
244	 * confidence grade from the most recent Report. Falls back to purple while
245	 * idle / connecting / verifying — i.e. before any Report has come in, OR if
246	 * the verifier is mid-cycle on a new turn (we keep the prior color until the
247	 * new Report lands, but reset to purple while actively verifying so the user
248	 * can tell something's in flight).
249	 *
250	 *   PERFECT / VERIFIED → green   (success)
251	 *   PARTIAL / FEEDBACK → orange  (working as designed, intermediate state)
252	 *   FAILED             → red     (verifier itself stuck; escalation needed)
253	 */
254	function bgForConfidence(confidence: Confidence | null, phase: Phase): string {
255	  // While actively running a verification cycle, show purple — the prior
256	  // confidence isn't "current" anymore. The bar will switch to the verdict
257	  // color when agent_end fires and the Report is parsed.
258	  if (phase === "verifying") return "\x1b[48;5;57m"; // purple
259	  if (phase === "connecting" || phase === "disconnected" || phase === "error") {
260	    return "\x1b[48;5;57m"; // purple — also for transient/error states
261	  }
262	  switch (confidence) {
263	    case "perfect":
264	    case "verified":
265	      return "\x1b[48;5;28m"; // green
266	    case "partial":
267	    case "feedback":
268	      return "\x1b[48;5;130m"; // orange
269	    case "failed":
270	      return "\x1b[48;5;124m"; // red
271	    default:
272	      return "\x1b[48;5;57m"; // purple — null / no Report yet
273	  }
274	}
275	
276	// ─── VerifierStatusBar ───────────────────────────────────────────────────────
277	
278	class VerifierStatusBar extends CustomEditor {
279	  override render(width: number): string[] {
280	    // Minimal bar — persona name (so it's obvious which agent is loaded),
281	    // the live phase, and the confidence grade (if a Report has come in).
282	    // Model/ctx live in the footer; sid is omitted; the input lock is
283	    // enforced architecturally so we don't need a visual cue.
284	    const left = ` ${state.personaName || "VERIFIER"} `;
285	    const phase = formatPhase(state.phase);
286	    const conf = state.confidence
287	      ? ` · ${state.confidence.toUpperCase()}`
288	      : "";
289	    const center = ` ${phase}${conf} `;
290	    const right = " ";
291	
292	    const raw = fullWidthAsciiBar(width, left, center, right);
293	
294	    // Background color reflects the verifier's confidence grade — green for
295	    // PERFECT/VERIFIED, orange for PARTIAL/UNSURE, red for FAILED, and the
296	    // default purple while idle/connecting/verifying (no Report yet).
297	    const bg = bgForConfidence(state.confidence, state.phase);
298	    const fgWhite = "\x1b[38;5;231m";
299	    const bold = "\x1b[1m";
300	    const reset = "\x1b[0m";
301	
302	    return [`${bg}${fgWhite}${bold}${raw}${reset}`];
303	  }
304	
305	  override handleInput(data: string): void {
306	    // The CustomEditor base class declares `keybindings` as private, so we
307	    // reach through `unknown`/`any` here to use it the same way the reference
308	    // editor does. This is intentional: we are deliberately mirroring the
309	    // shortcut-preservation logic from `full-bar-editor.ts` verbatim.
310	    const self = this as unknown as {
311	      keybindings: { matches(data: string, action: string): boolean };
312	    };
313	
314	    // Preserve extension shortcuts.
315	    if (this.onExtensionShortcut?.(data)) return;
316	
317	    // Preserve paste-image shortcut if configured.
318	    if (self.keybindings.matches(data, "app.clipboard.pasteImage")) {
319	      this.onPasteImage?.();
320	      return;
321	    }
322	
323	    // Preserve Escape / interrupt.
324	    if (self.keybindings.matches(data, "app.interrupt")) {
325	      if (!this.isShowingAutocomplete()) {
326	        const handler = this.onEscape ?? this.actionHandlers.get("app.interrupt");
327	        if (handler) {
328	          handler();
329	          return;
330	        }
331	      }
332	      super.handleInput(data);
333	      return;
334	    }
335	
336	    // Preserve Ctrl+D / exit when empty.
337	    if (self.keybindings.matches(data, "app.exit")) {
338	      if (this.getText().length === 0) {
339	        const handler = this.onCtrlD ?? this.actionHandlers.get("app.exit");
340	        if (handler) handler();
341	      }
342	      return;
343	    }
344	
345	    // Preserve other app-level actions, such as model switch shortcuts.
346	    for (const [action, handler] of this.actionHandlers) {
347	      if (
348	        action !== "app.interrupt" &&
349	        action !== "app.exit" &&
350	        self.keybindings.matches(data, action)
351	      ) {
352	        handler();
353	        return;
354	      }
355	    }
356	
357	    // Swallow all normal typing/Enter/etc. This is not an input field anymore.
358	  }
359	}
360	
361	// ─── Default factory ─────────────────────────────────────────────────────────
362	
363	export default function verifierExtension(pi: ExtensionAPI): void {
364	  pi.registerFlag("child", {
365	    type: "boolean",
366	    description: "Run as verifier child",
367	  });
368	  pi.registerFlag("builder-session", {
369	    type: "string",
370	    description: "Builder session ID to attach to",
371	  });
372	  pi.registerFlag("agent", {
373	    type: "string",
374	    description: "Path to verifier persona file",
375	  });
376	
377	  // Render the `🪝 builder event ...` system messages we emit on every
378	  // received `event` envelope. Single-line, faded, ANSI-aware truncation
379	  // is handled by `Text` itself.
380	  pi.registerMessageRenderer("builder-event", (message, _options, theme) => {
381	    const content =
382	      typeof message.content === "string"
383	        ? message.content
384	        : message.content
385	            .map((c) => (c.type === "text" ? c.text : ""))
386	            .join("");
387	    return new Text(theme.fg("muted", content), 0, 0);
388	  });
389	
390	  // ── verifier_prompt tool ─────────────────────────────────────────────────
391	  // The agent's only outbound channel back to the builder. Writes a
392	  // `prompt` envelope to the parent socket and awaits the matching
393	  // `prompt_ack` by `correlationId`. 60s timeout in case the builder is
394	  // hung; the agent treats a timeout as a genuine failure.
395	  pi.registerTool({
396	    name: "verifier_prompt",
397	    label: "Verifier Prompt",
398	    description:
399	      "Send a corrective user-style prompt to the builder agent. Use this to " +
400	      "request a follow-up action when verification fails. The message is " +
401	      "delivered to the builder via pi.sendUserMessage.",
402	    promptSnippet:
403	      "Send a corrective prompt to the builder when verification fails.",
404	    parameters: Type.Object({
405	      session_id: Type.String({
406	        description:
407	          "Builder session id (uuid). Use the value from your system Variables; never invent.",
408	      }),
409	      message: Type.String({
410	        description:
411	          "User-style corrective prompt to inject into the builder. Be specific and actionable.",
412	      }),
413	      deliver_as: Type.Optional(
414	        Type.Union([Type.Literal("followUp"), Type.Literal("steer")]),
415	      ),
416	    }),
417	    async execute(_toolCallId, params, _signal, _onUpdate, _ctx) {
418	      if (!state.parentConn || state.parentConn.destroyed) {
419	        return {
420	          content: [
421	            {
422	              type: "text",
423	              text:
424	                "✗ verifier_prompt rejected: not connected to builder (socket closed). " +
425	                "Cannot deliver corrective prompt right now.",
426	            },
427	          ],
428	          details: { ok: false, reason: "socket_closed" },
429	        };
430	      }
431	
432	      const correlationId = crypto.randomUUID();
433	      const envelope: Prompt = {
434	        type: "prompt",
435	        sessionId: params.session_id,
436	        message: params.message,
437	        deliverAs: params.deliver_as ?? "followUp",
438	        correlationId,
439	      };
440	
441	      // Set up the ack waiter before writing — the parent could in
442	      // principle reply faster than the next event-loop tick on a hot
443	      // local socket.
444	      const ackPromise = new Promise<PromptAck>((resolve, reject) => {
445	        const timeout = setTimeout(() => {
446	          state.pendingPromptAcks.delete(correlationId);
447	          reject(new Error("prompt_ack timeout (60s) — builder did not respond"));
448	        }, 60_000);
449	
450	        state.pendingPromptAcks.set(correlationId, (ack) => {
451	          clearTimeout(timeout);
452	          resolve(ack);
453	        });
454	      });
455	
456	      try {
457	        assertDirection(envelope, "verifier-to-builder");
458	        state.parentConn.write(encodeEnvelope(envelope));
459	      } catch (err) {
460	        state.pendingPromptAcks.delete(correlationId);
461	        return {
462	          content: [
463	            {
464	              type: "text",
465	              text: `✗ verifier_prompt failed to send: ${(err as Error).message}`,
466	            },
467	          ],
468	          details: { ok: false, reason: "write_failed", correlationId },
469	        };
470	      }
471	
472	      try {
473	        const ack = await ackPromise;
474	        // Mark the cycle so the status bar can show "prompted builder" on
475	        // the subsequent `failed` phase.
476	        state.promptedThisCycle = true;
477	        return {
478	          content: [
479	            {
480	              type: "text",
481	              text: ack.ok
482	                ? `✓ ack: prompt delivered to builder`
483	                : `✗ rejected: ${ack.error ?? "(no reason given)"}`,
484	            },
485	          ],
486	          details: { correlationId, ok: ack.ok, error: ack.error },
487	        };
488	      } catch (err) {
489	        return {
490	          content: [
491	            { type: "text", text: `✗ verifier_prompt failed: ${(err as Error).message}` },
492	          ],
493	          details: { ok: false, reason: "timeout", correlationId },
494	        };
495	      }
496	    },
497	  });
498	
499	  // ── Bash override (script-only enforcement, Q5) ──────────────────────────
500	  pi.on("tool_call", async (event: ToolCallEvent, _ctx): Promise<ToolCallEventResult | void> => {
501	    if (event.toolName !== "bash") return;
502	    // No bash_policy → no narrowing. The generic verifier persona omits
503	    // bash_policy so it can use pi's full default tool surface; domain
504	    // personas (verify_sqlite, etc.) declare one to lock bash to a single
505	    // allowed script.
506	    if (!state.bashPolicy) return;
507	
508	    const cmd = ((event.input as { command?: string })?.command ?? "").trim();
509	    const expected = `${state.bashPolicy.runner} ${state.bashPolicy.allowed_script}`;
510	
511	    if (cmd.startsWith(expected)) return; // allow.
512	
513	    return {
514	      block: true,
515	      reason: [
516	        "Bash is restricted to the verifier script.",
517	        `Allowed:   ${expected} <db> "<sqlite3 command>"`,
518	        `Received:  ${cmd}`,
519	        "",
520	        "Mutations (INSERT, UPDATE, DELETE, DROP, ALTER, etc.) are not permitted.",
521	        "Use the verify_sqlite.py wrapper. It accepts normal sqlite3 commands (dot-commands,",
522	        "SELECT, WITH, EXPLAIN, PRAGMA) and refuses anything that mutates state.",
523	        "",
524	        "Examples:",
525	        `  ${expected} users.db ".schema"`,
526	        `  ${expected} users.db "SELECT count(*) FROM users"`,
527	        `  ${expected} users.db "PRAGMA integrity_check"`,
528	      ].join("\n"),
529	    };
530	  });
531	
532	  // ── Defense-in-depth input lock (Q7) ─────────────────────────────────────
533	  // Block any input event that didn't originate from `pi.sendUserMessage`
534	  // (extension source). The CustomEditor swallows typing already; this is
535	  // belt-and-suspenders for RPC clients and other surprise sources.
536	  pi.on("input", async (event: InputEvent, ctx): Promise<InputEventResult> => {
537	    if (event.source === "extension") return { action: "continue" };
538	    ctx.ui.notify(
539	      "Verifier input is disabled — driven by builder events only.",
540	      "warning",
541	    );
542	    return { action: "handled" };
543	  });
544	
545	  // ── Verifier's own agent_end → emit Report envelope ──────────────────────
546	  pi.on("agent_end", async (_event: AgentEndEvent, ctx) => {
547	    if (!state.parentConn || state.parentConn.destroyed) return;
548	
549	    // Pull the most recent assistant message text out of the session.
550	    const entries = ctx.sessionManager.getEntries();
551	    let raw = "";
552	    for (let i = entries.length - 1; i >= 0; i--) {
553	      const entry = entries[i];
554	      if (entry?.type !== "message") continue;
555	      const msg = entry.message;
556	      if (msg.role !== "assistant") continue;
557	      raw = extractAssistantText(msg.content);
558	      break;
559	    }
560	    if (!raw) {
561	      // No assistant text at all — nothing to report on.
562	      state.phase = "error";
563	      state.errorDetail = "no assistant message";
564	      requestStatusRender(ctx);
565	      return;
566	    }
567	
568	    const report = parseReport(raw, state.currentTurnIndex);
569	    if (!report) {
570	      // Couldn't find a `## Report` block — surface the failure but don't
571	      // crash. The builder-side won't get a `report` envelope, which is the
572	      // signal that something went wrong.
573	      state.phase = "error";
574	      state.errorDetail = "report parse failed";
575	      requestStatusRender(ctx);
576	      return;
577	    }
578	
579	    state.phase =
580	      report.status === "verified"
581	        ? "verified"
582	        : report.status === "failed"
583	          ? "failed"
584	          : "unsure";
585	    state.confidence = report.confidence; // drives the bar's bg color
586	    requestStatusRender(ctx);
587	
588	    const envelope: Report = {
589	      type: "report",
590	      sessionId: state.builderSessionId,
591	      turnIndex: state.currentTurnIndex,
592	      status: report.status,
593	      confidence: report.confidence,
594	      summary: report.summary,
595	      sections: report.sections,
596	      raw,
597	    };
598	    try {
599	      assertDirection(envelope, "verifier-to-builder");
600	      state.parentConn.write(encodeEnvelope(envelope));
601	    } catch (err) {
602	      ctx.ui.notify(
603	        `verifier: failed to send report envelope: ${(err as Error).message}`,
604	        "error",
605	      );
606	    }
607	  });
608	
609	  // ── session_start: validate flags, install editor, connect socket ────────
610	  pi.on("session_start", async (_event: SessionStartEvent, ctx) => {
611	    // No-op when the file is loaded standalone (without --child). Lets us
612	    // share the same extension on the builder PATH without side effects.
613	    if (!pi.getFlag("child")) return;
614	
615	    state.uiCtx = ctx;
616	
617	    // Defensive .env load. The launcher already forwards env from the builder
618	    // via tmux `-e`, but if the user starts the verifier manually (or tmux
619	    // strips something), `.env` from this cwd backfills any missing vars.
620	    // Existing process.env values win — we only fill gaps.
621	    // Notify rule: silent on success; warn only when missing or unparseable.
622	    const envResult = await loadDotEnv(ctx.cwd);
623	    if (!envResult.loaded && envResult.reason) {
624	      ctx.ui.notify(`verifier: ${envResult.reason}`, "warning");
625	    }
626	
627	    const builderSession = pi.getFlag("builder-session");
628	    const agentPath = pi.getFlag("agent");
629	    if (typeof builderSession !== "string" || builderSession.length === 0) {
630	      ctx.ui.notify(
631	        "verifier: missing required flags --builder-session and --agent",
632	        "error",
633	      );
634	      return;
635	    }
636	    if (typeof agentPath !== "string" || agentPath.length === 0) {
637	      ctx.ui.notify(
638	        "verifier: missing required flags --builder-session and --agent",
639	        "error",
640	      );
641	      return;
642	    }
643	    state.builderSessionId = builderSession;
644	    state.agentPath = agentPath;
645	    // Derive the display name from the persona file: basename, strip `.md`,
646	    // uppercase. e.g. ".pi/verifier/agents/verify_sqlite.md" → "VERIFY_SQLITE".
647	    state.personaName = path.basename(agentPath, ".md").toUpperCase();
648	
649	    // Read frontmatter for runtime enforcement (bash policy + max_loops).
650	    // Body has already been templated by the launcher and passed via
651	    // --system-prompt; we don't re-template here.
652	    // bash_policy is optional — domain personas (e.g. verify_sqlite) declare
653	    // one to narrow bash to a single allowed script; the generic verifier
654	    // omits it and accepts pi's full default tool surface.
655	    let bashPolicy: BashPolicy | null;
656	    let maxLoops: number;
657	    try {
658	      const personaContent = readFileSync(state.agentPath, "utf-8");
659	      const persona = parseVerifierPersona(personaContent);
660	      bashPolicy = persona.frontmatter.bash_policy ?? null;
661	      maxLoops = persona.frontmatter.max_loops ?? 3;
662	    } catch (err) {
663	      ctx.ui.notify(
664	        `verifier: failed to load persona at ${state.agentPath}: ${(err as Error).message}`,
665	        "error",
666	      );
667	      return;
668	    }
669	    state.bashPolicy = bashPolicy;
670	    state.maxLoops = maxLoops;
671	
672	    // Replace the input editor with the status bar and install our minimal
673	    // custom footer (overrides Pi's default — we only show what's relevant
674	    // to the verifier: model, ctx usage, sid, total turns, phase glyph).
675	    if (ctx.hasUI) {
676	      ctx.ui.setEditorComponent(
677	        (tui, theme, kb) => new VerifierStatusBar(tui, theme, kb, {}),
678	      );
679	      installVerifierFooter(ctx);
680	    }
681	
682	    // Resolve the socket path. Prefer the canonical resolver — falling
683	    // back to the breadcrumb file would be marginally more robust against
684	    // a tmpdir reshuffle, but in v1 the builder writes the breadcrumb
685	    // pointing at the same canonical path the resolver computes here.
686	    try {
687	      const { socketPath } = resolveSocketPath(state.builderSessionId, ctx.cwd);
688	      state.socketPath = socketPath;
689	    } catch (err) {
690	      ctx.ui.notify(
691	        `verifier: socket path resolution failed: ${(err as Error).message}`,
692	        "error",
693	      );
694	      return;
695	    }
696	
697	    // Connect.
698	    connectToParent(pi, ctx);
699	  });
700	
701	  // ── session_shutdown: clean up socket + editor ───────────────────────────
702	  pi.on("session_shutdown", async (_event: SessionShutdownEvent, ctx) => {
703	    if (!pi.getFlag("child")) return;
704	    state.shuttingDown = true;
705	    teardown(ctx);
706	  });
707	}
708	
709	// ─── Connection management ───────────────────────────────────────────────────
710	
711	function connectToParent(pi: ExtensionAPI, ctx: ExtensionContext): void {
712	  const conn = net.createConnection(state.socketPath);
713	  state.parentConn = conn;
714	
715	  conn.on("connect", () => {
716	    state.lastAckTimestamp = Date.now();
717	    const hello: Hello = {
718	      type: "hello",
719	      role: "verifier",
720	      sessionId: state.builderSessionId,
721	      pid: process.pid,
722	    };
723	    try {
724	      assertDirection(hello, "verifier-to-builder");
725	      conn.write(encodeEnvelope(hello));
726	    } catch (err) {
727	      ctx.ui.notify(
728	        `verifier: failed to send hello: ${(err as Error).message}`,
729	        "error",
730	      );
731	    }
732	    requestStatusRender(ctx);
733	
734	    // Start liveness pings only after we've connected.
735	    startPingInterval(ctx);
736	  });
737	
738	  conn.on("error", (err) => {
739	    if (state.shuttingDown) return;
740	    ctx.ui.notify(
741	      `verifier: socket error: ${(err as Error).message}`,
742	      "error",
743	    );
744	  });
745	
746	  conn.on("close", () => {
747	    if (state.shuttingDown) return;
748	    state.phase = "disconnected";
749	    requestStatusRender(ctx);
750	    // Give the user a moment to see the disconnected status, then exit
751	    // cleanly. If the parent is genuinely gone, the tmux window dies with
752	    // us; if the user wanted to keep it, they can tmux-attach the corpse.
753	    setTimeout(() => {
754	      try {
755	        ctx.shutdown();
756	      } catch {
757	        // Best-effort — fall back to process.exit so the tmux window dies.
758	        process.exit(0);
759	      }
760	    }, 5000);
761	  });
762	
763	  // JSONL reader. Wrapped in an async IIFE so we don't unhandle-reject the
764	  // top-level factory; per-frame errors are surfaced via notify.
765	  void (async () => {
766	    try {
767	      for await (const envelope of readEnvelopes(conn)) {
768	        try {
769	          dispatchEnvelope(envelope, pi, ctx);
770	        } catch (err) {
771	          ctx.ui.notify(
772	            `verifier: dispatch error: ${(err as Error).message}`,
773	            "error",
774	          );
775	        }
776	      }
777	    } catch (err) {
778	      if (state.shuttingDown) return;
779	      ctx.ui.notify(
780	        `verifier: read loop ended: ${(err as Error).message}`,
781	        "warning",
782	      );
783	    }
784	  })();
785	}
786	
787	function dispatchEnvelope(envelope: Envelope, pi: ExtensionAPI, ctx: ExtensionContext): void {
788	  // The verifier consumes builder→verifier traffic. ping/pong/bye are
789	  // bidirectional in the matrix (both sides run liveness intervals; either
790	  // side may initiate teardown); the typed envelopes (hello_ack /
791	  // prompt_ack / event) are strictly directional and validated here.
792	  assertDirection(envelope, "builder-to-verifier");
793	  state.lastAckTimestamp = Date.now();
794	
795	  switch (envelope.type) {
796	    case "hello_ack": {
797	      state.helloAcked = true;
798	      state.phase = "connected";
799	      requestStatusRender(ctx);
800	      return;
801	    }
802	    case "prompt_ack": {
803	      const resolver = state.pendingPromptAcks.get(envelope.correlationId);
804	      if (resolver) {
805	        state.pendingPromptAcks.delete(envelope.correlationId);
806	        resolver(envelope);
807	      }
808	      return;
809	    }
810	    case "ping": {
811	      const pong: Pong = { type: "pong", nonce: envelope.nonce };
812	      // pong is bidirectional; this is the synchronous reply to a builder
813	      // ping. assertDirection is a programming-error guard.
814	      try {
815	        assertDirection(pong, "verifier-to-builder");
816	        state.parentConn?.write(encodeEnvelope(pong));
817	      } catch (err) {
818	        ctx.ui.notify(
819	          `verifier: failed to pong: ${(err as Error).message}`,
820	          "error",
821	        );
822	      }
823	      return;
824	    }
825	    case "pong": {
826	      state.pendingPongs = 0;
827	      return;
828	    }
829	    case "event": {
830	      handleBuilderEvent(envelope, pi, ctx);
831	      return;
832	    }
833	    case "bye": {
834	      state.shuttingDown = true;
835	      teardown(ctx);
836	      try {
837	        ctx.shutdown();
838	      } catch {
839	        process.exit(0);
840	      }
841	      return;
842	    }
843	    default:
844	      // Direction matrix excluded everything else, but TS still wants the
845	      // fallthrough.
846	      return;
847	  }
848	}
849	
850	function handleBuilderEvent(
851	  envelope: BuilderEvent,
852	  pi: ExtensionAPI,
853	  ctx: ExtensionContext,
854	): void {
855	  // Render the event as a visible system message in the verifier's
856	  // scrollback. The custom renderer is registered above.
857	  //
858	  // `deliverAs: "nextTurn"` is critical here — without it, sendMessage
859	  // defaults to "steer", which INJECTS the message into the verifier's
860	  // current stream between tool calls. That makes the verifier's LLM see
861	  // "🪝 builder event · start · turn N+1" mid-reasoning on turn N's
862	  // verification cycle, and it gets confused thinking a new turn started
863	  // while it's mid-Report. With "nextTurn", the message is queued for the
864	  // NEXT user turn (which will be turn N+1's verify_on_stop prompt) and
865	  // does not interrupt or pollute the current run's context. The custom
866	  // renderer still places the row in scrollback for operator visibility.
867	  const turnLabel = envelope.turnIndex !== undefined ? String(envelope.turnIndex) : "—";
868	  const iso = new Date(envelope.timestamp).toISOString();
869	  pi.sendMessage(
870	    {
871	      customType: "builder-event",
872	      content: `🪝 builder event · ${envelope.name} · turn ${turnLabel} · ${iso}`,
873	      details: envelope,
874	      display: true,
875	    },
876	    { deliverAs: "nextTurn" },
877	  );
878	
879	  switch (envelope.name) {
880	    case "start": {
881	      // Builder turn has begun. The Phase enum doesn't have a dedicated
882	      // "running" state (verifying covers the post-stop cycle), so we keep
883	      // state.phase at "connected" — our custom footer reads state.phase
884	      // and re-renders on tui.requestRender(). No setStatus needed.
885	      state.phase = "connected";
886	      requestStatusRender(ctx);
887	      return;
888	    }
889	    case "stop": {
890	      state.currentTurnIndex = envelope.turnIndex ?? state.currentTurnIndex;
891	      state.phase = "verifying";
892	      state.promptedThisCycle = false;
893	      // Reset confidence so the bar drops back to purple while we verify the
894	      // new turn. The next Report will set it again with the verdict color.
895	      state.confidence = null;
896	      requestStatusRender(ctx);
897	
898	      // Fire the verify_on_stop user prompt.
899	      const promptPath = path.join(
900	        ctx.cwd,
901	        ".pi",
902	        "verifier",
903	        "prompts",
904	        "verify_on_stop.md",
905	      );
906	      let template: string;
907	      try {
908	        template = readFileSync(promptPath, "utf-8");
909	      } catch (err) {
910	        ctx.ui.notify(
911	          `verifier: failed to read ${promptPath}: ${(err as Error).message}`,
912	          "error",
913	        );
914	        return;
915	      }
916	      const rendered = templateBody(template, {
917	        TURN_INDEX: String(state.currentTurnIndex),
918	        TIMESTAMP: new Date(envelope.timestamp).toISOString(),
919	        USER_PROMPT: envelope.userPrompt ?? "(no captured user prompt)",
920	        SESSION_FILE_START_LINE: String(envelope.sessionFileStartLine ?? 1),
921	        SESSION_FILE_END_LINE: String(envelope.sessionFileEndLine ?? 0),
922	      });
923	      try {
924	        // extension-source — passes through the input lock on this side.
925	        // `deliverAs: "followUp"` queues the prompt if the verifier is
926	        // already mid-turn on a previous stop event. Without this, a fast
927	        // builder (multi-turn user prompt) could fire stop N+1 while we're
928	        // still verifying turn N — Pi would either drop or interrupt. With
929	        // followUp, Pi appends the new user message to its queue and runs
930	        // it as soon as the current agent run completes. Order is preserved.
931	        pi.sendUserMessage(rendered, { deliverAs: "followUp" });
932	      } catch (err) {
933	        ctx.ui.notify(
934	          `verifier: sendUserMessage failed: ${(err as Error).message}`,
935	          "error",
936	        );
937	      }
938	      return;
939	    }
940	    case "error": {
941	      state.phase = "error";
942	      state.errorDetail = envelope.detail ?? "(no detail)";
943	      requestStatusRender(ctx);
944	      return;
945	    }
946	  }
947	}
948	
949	// ─── Liveness ────────────────────────────────────────────────────────────────
950	
951	function startPingInterval(ctx: ExtensionContext): void {
952	  if (state.pingInterval) {
953	    clearInterval(state.pingInterval);
954	  }
955	  state.pingInterval = setInterval(() => {
956	    if (!state.parentConn || state.parentConn.destroyed) return;
957	    state.pendingPongs += 1;
958	    if (state.pendingPongs >= 2) {
959	      // Two missed pongs → parent gone. Mark disconnected, then fall
960	      // through to the close handler's 5s exit.
961	      state.phase = "disconnected";
962	      requestStatusRender(ctx);
963	      try {
964	        state.parentConn.destroy();
965	      } catch {
966	        // ignore
967	      }
968	      return;
969	    }
970	    const ping: Ping = { type: "ping", nonce: crypto.randomUUID() };
971	    try {
972	      // ping is bidirectional; assert direction for symmetry with other
973	      // outbound writes. Will not throw since the matrix permits it.
974	      assertDirection(ping, "verifier-to-builder");
975	      state.parentConn.write(encodeEnvelope(ping));
976	    } catch {
977	      // Write failures will surface via the close handler.
978	    }
979	  }, 10_000);
980	}
981	
982	// ─── Teardown ────────────────────────────────────────────────────────────────
983	
984	function teardown(ctx: ExtensionContext): void {
985	  if (state.pingInterval) {
986	    clearInterval(state.pingInterval);
987	    state.pingInterval = null;
988	  }
989	
990	  // Send `bye` if we still have a live socket.
991	  if (state.parentConn && !state.parentConn.destroyed) {
992	    try {
993	      state.parentConn.write(
994	        encodeEnvelope({ type: "bye", reason: "verifier shutting down" }),
995	      );
996	    } catch {
997	      // ignore
998	    }
999	    try {
1000	      state.parentConn.end();
1001	    } catch {
1002	      // ignore
1003	    }
1004	  }
1005	
1006	  // Restore the default editor. Defensive — `ctx.ui` may be a no-op in
1007	  // print mode.
1008	  if (ctx.hasUI) {
1009	    try {
1010	      ctx.ui.setEditorComponent(undefined);
1011	      ctx.ui.setFooter(undefined);
1012	    } catch {
1013	      // ignore
1014	    }
1015	  }
1016	}
1017	
1018	// ─── Custom footer ───────────────────────────────────────────────────────────
1019	
1020	/**
1021	 * Install the verifier's minimal footer. Replaces Pi's default footer entirely
1022	 * (per Q-amendment: we only want model · ctx-bar · sid · turn · phase).
1023	 *
1024	 * Render reads from `state.*` directly, so any state mutation followed by
1025	 * `requestStatusRender(ctx)` (which calls `ctx.ui.requestRender?.()`) refreshes
1026	 * the line. Pattern adapted from the upstream `minimal.ts` reference.
1027	 */
1028	function installVerifierFooter(ctx: ExtensionContext): void {
1029	  ctx.ui.setFooter((_tui, theme, _footerData) => ({
1030	    dispose: () => {},
1031	    invalidate() {},
1032	    render(width: number): string[] {
1033	      const model = ctx.model?.id ?? "no-model";
1034	      const usage = ctx.getContextUsage?.();
1035	      const pct = usage && usage.percent !== null ? usage.percent : 0;
1036	      const filled = Math.round(pct / 10);
1037	      const bar = "#".repeat(filled) + "-".repeat(Math.max(0, 10 - filled));
1038	
1039	      // Verifier footer is now just model + ctx-bar. Phase lives ONLY in
1040	      // the top status bar (VerifierStatusBar) — no duplication. sid and
1041	      // turn are also omitted (sid: builder footer carries the canonical
1042	      // one; turn: visible in scrollback as builder-event system messages).
1043	      const left = theme.fg("dim", ` ${model}`);
1044	      const right = theme.fg("dim", ` [${bar}] ${Math.round(pct)}% `);
1045	      const padLen = Math.max(1, width - visibleWidth(left) - visibleWidth(right));
1046	      return [truncateToWidth(left + " ".repeat(padLen) + right, width)];
1047	    },
1048	  }));
1049	}
1050	
1051	/**
1052	 * Trigger a footer re-render after mutating `state.*`. The footer reads from
1053	 * state on each render, so we just nudge the TUI. Cheap and idempotent.
1054	 */
1055	function requestStatusRender(ctx: ExtensionContext): void {
1056	  if (!ctx.hasUI) return;
1057	  // Re-trigger render via setFooter (idempotent install). Pi's TUI batches
1058	  // renders so calling this on every state change is fine.
1059	  installVerifierFooter(ctx);
1060	}
1061	
1062	// ─── Report parsing ──────────────────────────────────────────────────────────
1063	
1064	const REPORT_HEADERS = [
1065	  "What did you verify?",
1066	  "What could you not verify?",
1067	  "What feedback did you give?",
1068	  "What do you need from me to verify this next time?",
1069	  "Verification metadata",
1070	] as const;
1071	
1072	/**
1073	 * Pull the `## Report` block out of the assistant's last message and split
1074	 * it into its known H3 sections. Returns null if the block is missing or
1075	 * the STATUS line can't be parsed — both of which the caller treats as
1076	 * "no report this cycle".
1077	 */
1078	function parseReport(raw: string, _turnIndex: number): ParsedReport | null {
1079	  const reportIdx = raw.search(/^##\s+Report\s*$/m);
1080	  if (reportIdx === -1) return null;
1081	  const reportBody = raw.slice(reportIdx);
1082	
1083	  // STATUS line — case-insensitive, anywhere on its own line in the block.
1084	  const statusMatch = reportBody.match(/^\s*STATUS\s*:\s*(verified|failed|unsure)\b/im);
1085	  if (!statusMatch) return null;
1086	  const status = statusMatch[1]!.toLowerCase() as ParsedReport["status"];
1087	
1088	  // CONFIDENCE line — case-insensitive, optional. If the agent omits it
1089	  // (e.g. older persona didn't know about it), derive a sensible default
1090	  // from STATUS so the bar still gets a meaningful color:
1091	  //   verified → "verified" (green)   failed → "feedback" (orange)   unsure → "failed" (red)
1092	  // Reasoning for the fallback: STATUS:failed implies the verifier identified
1093	  // a problem and ideally called verifier_prompt → FEEDBACK. STATUS:unsure
1094	  // implies the verifier itself couldn't make a judgment → FAILED.
1095	  const confMatch = reportBody.match(/^\s*CONFIDENCE\s*:\s*(perfect|verified|partial|feedback|failed)\b/im);
1096	  const confidence: Confidence = confMatch
1097	    ? (confMatch[1]!.toLowerCase() as Confidence)
1098	    : (status === "verified" ? "verified" : status === "failed" ? "feedback" : "failed");
1099	
1100	  // Split the body on H3 boundaries to populate sections.
1101	  const sections: Record<string, string> = {};
1102	  // We only collect sections matching the known header set; unknown H3s
1103	  // are ignored.
1104	  for (const header of REPORT_HEADERS) {
1105	    const re = new RegExp(
1106	      `^###\\s+${escapeRegex(header)}\\s*$([\\s\\S]*?)(?=^###\\s|^##\\s|\\Z)`,
1107	      "m",
1108	    );
1109	    const m = reportBody.match(re);
1110	    if (m && m[1]) {
1111	      sections[header] = m[1].trim();
1112	    }
1113	  }
1114	
1115	  // Summary — first non-empty line of "What did you verify?" or fallback.
1116	  const verifiedSection = sections["What did you verify?"];
1117	  let summary: string;
1118	  if (verifiedSection) {
1119	    const firstLine = verifiedSection.split("\n").find((l) => l.trim().length > 0);
1120	    summary = (firstLine ?? "").trim();
1121	  } else {
1122	    summary = "";
1123	  }
1124	  if (!summary) {
1125	    summary = `${status} for turn ${state.currentTurnIndex}`;
1126	  }
1127	
1128	  return { status, confidence, summary, sections };
1129	}
1130	
1131	function escapeRegex(s: string): string {
1132	  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
1133	}
1134	
1135	// ─── Assistant content extraction ────────────────────────────────────────────
1136	
1137	/**
1138	 * Pull the concatenated text content out of an assistant message. We only
1139	 * care about TextContent blocks — thinking and tool calls aren't part of
1140	 * the user-facing "## Report" surface.
1141	 */
1142	function extractAssistantText(content: unknown): string {
1143	  if (typeof content === "string") return content;
1144	  if (!Array.isArray(content)) return "";
1145	  const parts: string[] = [];
1146	  for (const block of content) {
1147	    if (
1148	      block &&
1149	      typeof block === "object" &&
1150	      "type" in block &&
1151	      (block as { type: unknown }).type === "text" &&
1152	      typeof (block as { text?: unknown }).text === "string"
1153	    ) {
1154	      parts.push((block as { text: string }).text);
1155	    }
1156	  }
1157	  return parts.join("\n");
1158	}
1159

