290	      sendEnvelope({
291	        type: "event",
292	        name: "start",
293	        sessionId: state.sessionId,
294	        turnIndex: state.turnIndex,
295	        timestamp: Date.now(),
296	        userPrompt: state.lastUserPrompt,
297	        sessionFileStartLine: state.turnStartLine,
298	      });
299	    } catch (err) {
300	      reportEventError(err);
301	    }
302	  });
