342	  // ─── Internal: attach() — the lifecycle entry point ───────────────────
343	
344	  async function attach(ctx: ExtensionContext | ExtensionCommandContext): Promise<void> {
345	    if (state.attached || state.spawnInFlight) {
346	      safeNotify(ctx, "verifier already attached", "info");
347	      return;
348	    }
349	    state.spawnInFlight = true;
350	    state.phase = "spawning";
351	    setFooter(ctx, "spawning");
352	
353	    try {
354	      // Resolve repo root from this file's location: apps/verifier/verifiable.ts
355	      // → repo root is three levels up.
356	      const here = fileURLToPath(import.meta.url);
357	      const runtimeRoot = path.resolve(path.dirname(here), "..", "..");
358	
359	      // Domain persona — defaults to verify_sqlite, overridable via the
360	      // --verifier-agent <name> launch flag. The flag value is the bare
361	      // persona name (no .md, no path); we resolve it under
362	      // .pi/verifier/agents/ relative to the project cwd.
363	      const agentNameRaw = pi.getFlag("verifier-agent");
364	      const agentName =
365	        typeof agentNameRaw === "string" && agentNameRaw.length > 0
366	          ? agentNameRaw
367	          : "verifier";
368	      const agentPath = path.resolve(
369	        ctx.cwd,
370	        ".pi/verifier/agents",
371	        `${agentName}.md`,
372	      );
373	
374	      // Pull max_loops from the persona before spawning so the builder-side
375	      // counter matches the verifier's authoritative limit.
376	      try {
377	        const personaContent = await fs.readFile(agentPath, "utf8");
378	        const { frontmatter } = parseVerifierPersona(personaContent);
379	        if (typeof frontmatter.max_loops === "number" && frontmatter.max_loops > 0) {
380	          state.maxLoops = frontmatter.max_loops;
381	        }
382	      } catch (err) {
383	        // Persona is required for spawn; bail loudly via notify AND a
384	        // sticky system message so the user sees it in scrollback (not
385	        // just a transient toast).
386	        const msg = (err as Error).message ?? String(err);
387	        safeNotify(ctx, `verifier: failed to read persona at ${agentPath}: ${msg}`, "error");
388	        surfaceVerifierError(
389	          [
390	            `Could not load verifier persona at:`,
391	            `  ${agentPath}`,
392	            ``,
393	            `Reason: ${msg}`,
394	            ``,
395	            `Check that the file exists and the frontmatter is well-formed`,
396	            `(required: name, description, tools, model, domain).`,
397	          ].join("\n"),
398	        );
399	        state.phase = "error";
400	        setFooter(ctx, "error");
401	        state.spawnInFlight = false;
402	        return;
403	      }
404	
405	      // Resolve the builder session file. Fall back to the conventional
406	      // location if the session manager doesn't expose one (in-memory
407	      // sessions, e.g. ephemeral RPC mode).
408	      const sessionFile = ctx.sessionManager.getSessionFile();
409	      const builderSessionFile =
410	        sessionFile ?? path.join(os.homedir(), ".pi/agent/sessions", `${state.sessionId}.jsonl`);
411	
412	      // Resolve socket paths up-front so we can stash them on state for
413	      // cleanup, then bind the server before launching the child so the
414	      // child's `hello` always lands on a listening peer.
415	      const { socketPath, refPath } = resolveSocketPath(state.sessionId, ctx.cwd);
416	      state.socketPath = socketPath;
417	      state.refPath = refPath;
418	
419	      await startSocketServer(ctx);
420	
421	      // Launcher writes the breadcrumb + ensures /tmp/pi-verifier/.
422	      // Stash the artifact paths it returns so the spawn-timeout diagnostic
423	      // can read pi's actual stderr AND tell the user how to reproduce the
424	      // spawn manually (`bash <wrapperPath>`).
425	      try {
426	        const spawnResult = await spawnVerifierChild({
427	          sessionId: state.sessionId,
428	          agentPath,
429	          runtimeRoot,
430	          cwd: ctx.cwd,
431	          settings: undefined,
432	          builderSessionFile,
433	        });
434	        state.spawnWrapperPath = spawnResult.wrapperPath;
435	        state.spawnStderrLogPath = spawnResult.stderrLogPath;
436	      } catch (err) {
437	        const msg = (err as Error).message ?? String(err);
438	        safeNotify(ctx, `verifier: launcher failed: ${msg}`, "error");
439	        surfaceVerifierError(
440	          [
441	            `Verifier launcher threw before tmux could start the child.`,
442	            ``,
443	            `Reason: ${msg}`,
444	            ``,
445	            `This usually means tmux isn't installed, the persona file is`,
446	            `unreadable, or the resolved socket path exceeds macOS's 104-byte`,
447	            `sun_path limit.`,
448	          ].join("\n"),
449	        );
450	        state.phase = "error";
451	        setFooter(ctx, "error");
452	        // Tear the server back down — no peer will ever connect.
453	        await stopSocketServer();
454	        state.spawnInFlight = false;
455	        return;
456	      }
457	
458	      state.attached = true;
459	      // The verifier child has been spawned, but won't appear on the
460	      // socket until it sends `hello` — so the footer stays "spawning"
461	      // here. The dispatch handler flips it to "connected" on hello.
462	      setFooter(ctx, "spawning");
463	      installCrashForwarders();
464	
465	      // Arm the spawn-hello timeout. If the child fails to come up cleanly
466	      // (most common cause: invalid `model:` in the persona — pi exits with
467	      // an "unknown model" error before binding the socket), the builder
468	      // would otherwise sit on "spawning" forever with no signal. Diagnose
469	      // on fire and surface a system message.
470	      armSpawnTimeout(ctx);
471	    } finally {
472	      state.spawnInFlight = false;
473	    }
474	  }
