476	  // ─── Internal: socket server ──────────────────────────────────────────
477	
478	  async function startSocketServer(ctx: ExtensionContext): Promise<void> {
479	    // Ensure /tmp/pi-verifier/ exists with 0700 perms BEFORE listen().
480	    // The launcher's spawnVerifierChild also calls this, but it runs after
481	    // we bind — and on macOS, listen() against a non-existent parent dir
482	    // returns EACCES (not ENOENT), which masks the real cause.
483	    await ensureSocketDir();
484	
485	    // If a stale socket file is present (previous crash), unlink it so
486	    // listen() doesn't EADDRINUSE.
487	    try {
488	      await fs.unlink(state.socketPath);
489	    } catch (err) {
490	      if ((err as NodeJS.ErrnoException).code !== "ENOENT") {
491	        // Permissions or other I/O — surface but keep going; listen()
492	        // will report the real error if any.
493	        safeNotify(ctx, 
494	          `verifier: failed to unlink stale socket: ${(err as Error).message}`,
495	          "warning",
496	        );
497	      }
498	    }
499	
500	    const server = net.createServer((conn) => handleConnection(conn, ctx));
501	    state.socketServer = server;
502	
503	    await new Promise<void>((resolve, reject) => {
504	      const onError = (err: Error): void => {
505	        server.removeListener("listening", onListening);
506	        reject(err);
507	      };
508	      const onListening = (): void => {
509	        server.removeListener("error", onError);
510	        resolve();
511	      };
512	      server.once("error", onError);
513	      server.once("listening", onListening);
514	      server.listen(state.socketPath);
515	    });
516	  }
517	
518	  function handleConnection(conn: net.Socket, ctx: ExtensionContext): void {
519	    if (state.verifierConn) {
520	      // Only one verifier per builder. Refuse second connections.
521	      try {
522	        conn.write(encodeEnvelope({ type: "bye", reason: "duplicate connection" }));
523	      } catch {
524	        // ignore
525	      }
526	      conn.destroy();
527	      return;
528	    }
529	    state.verifierConn = conn;
530	
531	    conn.on("close", () => {
532	      cleanupConnection(ctx);
533	    });
534	    conn.on("error", (err) => {
535	      safeNotify(ctx, `verifier: socket error: ${err.message}`, "warning");
536	    });
537	
538	    void readEnvelopeLoop(conn, ctx);
539	  }
540	
541	  async function readEnvelopeLoop(conn: net.Socket, ctx: ExtensionContext): Promise<void> {
542	    try {
543	      for await (const envelope of readEnvelopes(conn)) {
544	        try {
545	          assertDirection(envelope, "verifier-to-builder");
546	        } catch (err) {
547	          safeNotify(ctx, `verifier: dropped envelope (${(err as Error).message})`, "warning");
548	          continue;
549	        }
550	        try {
551	          await dispatch(envelope, conn, ctx);
552	        } catch (err) {
553	          safeNotify(ctx, 
554	            `verifier: dispatch error on ${envelope.type}: ${(err as Error).message}`,
555	            "warning",
556	          );
557	        }
558	      }
559	    } catch (err) {
560	      // Parser errors (bad JSONL) end up here; log and let `close` fire.
561	      safeNotify(ctx, `verifier: read loop ended: ${(err as Error).message}`, "warning");
562	    }
563	  }
564	
565	  async function dispatch(
566	    envelope: Envelope,
567	    conn: net.Socket,
568	    ctx: ExtensionContext,
569	  ): Promise<void> {
570	    if (isHello(envelope)) {
571	      conn.write(
572	        encodeEnvelope({ type: "hello_ack", sessionId: state.sessionId }),
573	      );
574	      // Hello arrived in time — disarm the diagnostic timer.
575	      clearSpawnTimeout();
576	      state.phase = "connected";
577	      setFooter(ctx, "connected");
578	      startLiveness(conn, ctx);
579	      return;
580	    }
581	
582	    if (isPrompt(envelope)) {
583	      await handlePrompt(envelope, conn, ctx);
584	      return;
585	    }
586	
587	    if (isReport(envelope)) {
588	      handleReport(envelope);
589	      return;
590	    }
591	
592	    if (isPing(envelope)) {
593	      conn.write(encodeEnvelope({ type: "pong", nonce: envelope.nonce }));
594	      return;
595	    }
596	
597	    if (isPong(envelope)) {
598	      state.pendingPongs = 0;
599	      state.pingNonces.delete(envelope.nonce);
600	      return;
601	    }
602	
603	    if (isBye(envelope)) {
604	      safeNotify(ctx, `verifier: bye (${envelope.reason})`, "info");
605	      cleanupConnection(ctx);
606	      return;
607	    }
608	
609	    // hello_ack / prompt_ack / event / pong on this side would already
610	    // have been rejected by assertDirection. Safety net:
611	    safeNotify(ctx, `verifier: unexpected envelope type "${envelope.type}"`, "warning");
612	  }
613	
614	  async function handlePrompt(
615	    envelope: Prompt,
616	    conn: net.Socket,
617	    _ctx: ExtensionContext,
618	  ): Promise<void> {
619	    if (envelope.sessionId !== state.sessionId) {
620	      const ack: PromptAck = {
621	        type: "prompt_ack",
622	        sessionId: state.sessionId,
623	        correlationId: envelope.correlationId,
624	        ok: false,
625	        error: `sessionId mismatch (got ${envelope.sessionId}, expected ${state.sessionId})`,
626	      };
627	      conn.write(encodeEnvelope(ack));
628	      return;
629	    }
630	
631	    state.loopCount += 1;
632	
633	    if (state.loopCount > state.maxLoops) {
634	      const ack: PromptAck = {
635	        type: "prompt_ack",
636	        sessionId: state.sessionId,
637	        correlationId: envelope.correlationId,
638	        ok: false,
639	        error: "max loops exceeded",
640	      };
641	      conn.write(encodeEnvelope(ack));
642	
643	      const escalation =
644	        `Verifier failed ${state.loopCount - 1} times — escalating to human.\n\n` +
645	        (state.lastReportRaw.length > 0
646	          ? `Latest report:\n\n${state.lastReportRaw}`
647	          : "(no report content captured)");
648	      // `deliverAs: "nextTurn"` so the escalation lands in the builder's
649	      // scrollback at a clean turn boundary — never interleaved between
650	      // the builder's tool calls mid-stream.
651	      pi.sendMessage(
652	        {
653	          customType: "verifier-escalation",
654	          content: escalation,
655	          display: true,
656	        },
657	        { deliverAs: "nextTurn" },
658	      );
659	      return;
660	    }
661	
662	    // Mark the upcoming injected message as extension-sourced so our
663	    // before_agent_start handler will skip resetting loopCount.
664	    state.injectedNext = true;
665	    try {
666	      pi.sendUserMessage(envelope.message, {
667	        deliverAs: envelope.deliverAs ?? "followUp",
668	      });
669	    } catch (err) {
670	      // Roll back the flag; the injection failed.
671	      state.injectedNext = false;
672	      const ack: PromptAck = {
673	        type: "prompt_ack",
674	        sessionId: state.sessionId,
675	        correlationId: envelope.correlationId,
676	        ok: false,
677	        error: `sendUserMessage failed: ${(err as Error).message}`,
678	      };
679	      conn.write(encodeEnvelope(ack));
680	      return;
681	    }
682	
683	    const ack: PromptAck = {
684	      type: "prompt_ack",
685	      sessionId: state.sessionId,
686	      correlationId: envelope.correlationId,
687	      ok: true,
688	    };
689	    conn.write(encodeEnvelope(ack));
690	  }
691	
692	  function handleReport(envelope: Report): void {
693	    // The verifier already renders its full `## Report` block in its own
694	    // window's scrollback. We intentionally do NOT echo it into the builder's
695	    // chat — engineers reading the builder pane don't want a duplicate of
696	    // what's already visible in the verifier window. We just stash the raw
697	    // text so the max-loops escalation path can include it inline.
698	    state.lastReportRaw = envelope.raw;
699	  }
