701	  // ─── Internal: spawn diagnostic (failure path only) ───────────────────
702	
703	  /**
704	   * Surface an inline system message in the builder's chat. Failure-path
705	   * only — the happy path (hello arrives in time) is silent because the
706	   * input-bar status already conveys "connected." Persistent in scrollback
707	   * (unlike `notify(...)` toasts) so the operator can scroll back and see
708	   * the error after looking away.
709	   */
710	  function surfaceVerifierError(content: string): void {
711	    try {
712	      // `deliverAs: "nextTurn"` so this lands in the builder's scrollback
713	      // for the operator to see WITHOUT interrupting whatever the builder
714	      // agent might currently be streaming. Default ("steer") would inject
715	      // between the builder's tool calls and pollute its context.
716	      pi.sendMessage(
717	        {
718	          customType: "verifier-error",
719	          content,
720	          display: true,
721	        },
722	        { deliverAs: "nextTurn" },
723	      );
724	    } catch {
725	      // best-effort — fall back to stderr if pi's send path is broken
726	      process.stderr.write(`[verifier-error]\n${content}\n`);
727	    }
728	  }
729	
730	  function armSpawnTimeout(ctx: ExtensionContext): void {
731	    clearSpawnTimeout();
732	    state.spawnTimeout = setTimeout(() => {
733	      // Re-check inside the firing closure — phase may have transitioned
734	      // out of `spawning` between when we armed and when we fire.
735	      if (state.phase !== "spawning") return;
736	      void diagnoseSpawnFailure(ctx);
737	    }, SPAWN_HELLO_TIMEOUT_MS);
738	  }
739	
740	  function clearSpawnTimeout(): void {
741	    if (state.spawnTimeout) {
742	      clearTimeout(state.spawnTimeout);
743	      state.spawnTimeout = null;
744	    }
745	  }
746	
747	  /**
748	   * The verifier child failed to send `hello` within the timeout. Read the
749	   * captured stderr (the wrapper redirects pi's stderr to a log file via
750	   * `tee`), check tmux liveness, and surface a system message that names
751	   * pi's actual error — not a generic timeout. Reset state so the user
752	   * can retry via `/verify`.
753	   */
754	  async function diagnoseSpawnFailure(ctx: ExtensionContext): Promise<void> {
755	    const tmuxSession = `verifier-${state.sessionId}`;
756	    let alive = false;
757	    try {
758	      await execFileP("tmux", ["has-session", "-t", tmuxSession]);
759	      alive = true;
760	    } catch {
761	      alive = false;
762	    }
763	
764	    const stderrTail = await readStderrTail(state.spawnStderrLogPath);
765	
766	    const sections: string[] = [];
767	    if (alive) {
768	      sections.push(
769	        `Verifier did not connect within ${SPAWN_HELLO_TIMEOUT_MS / 1000}s.`,
770	        ``,
771	        `The tmux session \`${tmuxSession}\` is still alive — pi is running`,
772	        `but never reached the socket-connect path. Likely cause: the verifier`,
773	        `extension threw before \`net.createConnection\`, OR the socket dir`,
774	        `permissions changed.`,
775	      );
776	    } else {
777	      sections.push(
778	        `Verifier child died before connecting.`,
779	        ``,
780	        `The tmux session \`${tmuxSession}\` is gone — pi exited shortly`,
781	        `after spawn. The captured stderr below should name the cause.`,
782	      );
783	    }
784	
785	    if (stderrTail) {
786	      sections.push(``, `── pi stderr (tail) ──`, stderrTail.trimEnd());
787	    } else {
788	      sections.push(
789	        ``,
790	        `── pi stderr ──`,
791	        `(no stderr captured — log at ${state.spawnStderrLogPath} is empty or unreadable)`,
792	      );
793	    }
794	
795	    sections.push(
796	      ``,
797	      `Reproduce manually:  bash ${state.spawnWrapperPath}`,
798	    );
799	
800	    surfaceVerifierError(sections.join("\n"));
801	
802	    state.phase = "error";
803	    state.attached = false;
804	    setFooter(ctx, "error");
805	    removeCrashForwarders();
806	    await stopSocketServer().catch(() => undefined);
807	    // Best-effort kill of any straggler tmux session (no-op if already gone).
808	    void killVerifierChild(state.sessionId).catch(() => undefined);
809	  }
810	
811	  /**
812	   * Read the tail of the wrapper's stderr log, capped to keep the system
813	   * message readable. Returns "" if the file is missing/empty/unreadable —
814	   * the caller surfaces a fallback note in that case.
815	   *
816	   * 4 KB / 60 lines is enough for pi's typical "model not found" / import
817	   * traceback / argparse error without flooding the chat. The wrapper
818	   * truncates the log on each spawn so we never serve up stale content
819	   * from a previous run.
820	   */
821	  async function readStderrTail(logPath: string): Promise<string> {
822	    if (!logPath) return "";
823	    try {
824	      const buf = await fs.readFile(logPath, "utf8");
825	      if (!buf) return "";
826	      const MAX_BYTES = 4096;
827	      const MAX_LINES = 60;
828	      let tail = buf.length > MAX_BYTES ? buf.slice(buf.length - MAX_BYTES) : buf;
829	      const lines = tail.split("\n");
830	      if (lines.length > MAX_LINES) {
831	        tail = lines.slice(lines.length - MAX_LINES).join("\n");
832	      }
833	      return tail;
834	    } catch {
835	      return "";
836	    }
837	  }
