839	  // ─── Internal: liveness ───────────────────────────────────────────────
840	
841	  function startLiveness(conn: net.Socket, ctx: ExtensionContext): void {
842	    if (state.pingInterval) return;
843	    state.pingInterval = setInterval(() => {
844	      sendPing(conn, ctx);
845	    }, 10_000);
846	  }
847	
848	  function sendPing(conn: net.Socket, ctx: ExtensionContext): void {
849	    if (state.verifierConn !== conn || conn.destroyed) {
850	      stopLiveness();
851	      return;
852	    }
853	    const nonce = randomUUID();
854	    state.pingNonces.add(nonce);
855	
856	    try {
857	      conn.write(encodeEnvelope({ type: "ping", nonce }));
858	    } catch {
859	      // write failed — the close handler will tear down state.
860	      return;
861	    }
862	
863	    setTimeout(() => {
864	      if (state.pingNonces.has(nonce)) {
865	        state.pingNonces.delete(nonce);
866	        state.pendingPongs += 1;
867	        if (state.pendingPongs >= 2) {
868	          safeNotify(ctx, "verifier: 2 missed pongs — declaring dead", "warning");
869	          declareDead(ctx);
870	        }
871	      }
872	    }, 10_000);
873	  }
874	
875	  function stopLiveness(): void {
876	    if (state.pingInterval) {
877	      clearInterval(state.pingInterval);
878	      state.pingInterval = null;
879	    }
880	    state.pingNonces.clear();
881	    state.pendingPongs = 0;
882	  }
883	
884	  function declareDead(ctx: ExtensionContext): void {
885	    stopLiveness();
886	    if (state.verifierConn) {
887	      try {
888	        state.verifierConn.destroy();
889	      } catch {
890	        // ignore
891	      }
892	    }
893	    void killVerifierChild(state.sessionId).catch(() => undefined);
894	    state.phase = "disconnected";
895	    state.attached = false;
896	    state.verifierConn = null;
897	    removeCrashForwarders();
898	    setFooter(ctx, "disconnected");
899	  }
900	
901	  function cleanupConnection(ctx: ExtensionContext): void {
902	    stopLiveness();
903	    state.verifierConn = null;
904	    state.attached = false;
905	    state.phase = "disconnected";
906	    removeCrashForwarders();
907	    setFooter(ctx, "disconnected");
908	  }
909	
910	  // ─── Internal: detach (session_shutdown teardown) ─────────────────────
911	
912	  async function detach(): Promise<void> {
913	    if (state.verifierConn) {
914	      try {
915	        state.verifierConn.write(
916	          encodeEnvelope({ type: "bye", reason: "session_shutdown" }),
917	        );
918	      } catch {
919	        // ignore
920	      }
921	    }
922	    stopLiveness();
923	
924	    if (state.verifierConn) {
925	      try {
926	        state.verifierConn.end();
927	      } catch {
928	        // ignore
929	      }
930	      state.verifierConn = null;
931	    }
932	
933	    await stopSocketServer();
934	
935	    if (state.socketPath && state.refPath) {
936	      try {
937	        await cleanup(state.socketPath, state.refPath);
938	      } catch {
939	        // best-effort
940	      }
941	    }
942	
943	    try {
944	      await killVerifierChild(state.sessionId);
945	    } catch {
946	      // best-effort
947	    }
948	
949	    state.attached = false;
950	    state.phase = "disconnected";
951	    removeCrashForwarders();
952	  }
953	
954	  async function stopSocketServer(): Promise<void> {
955	    const server = state.socketServer;
956	    if (!server) return;
957	    state.socketServer = null;
958	    await new Promise<void>((resolve) => {
959	      server.close(() => resolve());
960	    });
961	  }
962	
963	  // ─── Internal: crash forwarders (only while attached) ─────────────────
964	
965	  function installCrashForwarders(): void {
966	    if (state.uncaughtListener || state.unhandledListener) return;
967	    const onUncaught = (err: unknown): void => {
968	      sendEnvelope({
969	        type: "event",
970	        name: "error",
971	        sessionId: state.sessionId,
972	        detail: errMessage(err),
973	        timestamp: Date.now(),
974	      });
975	    };
976	    const onUnhandled = (reason: unknown): void => {
977	      sendEnvelope({
978	        type: "event",
979	        name: "error",
980	        sessionId: state.sessionId,
981	        detail: errMessage(reason),
982	        timestamp: Date.now(),
983	      });
984	    };
985	    state.uncaughtListener = onUncaught;
986	    state.unhandledListener = onUnhandled;
987	    process.on("uncaughtException", onUncaught);
988	    process.on("unhandledRejection", onUnhandled);
989	  }
990	
991	  function removeCrashForwarders(): void {
992	    if (state.uncaughtListener) {
993	      process.removeListener("uncaughtException", state.uncaughtListener);
994	      state.uncaughtListener = null;
995	    }
996	    if (state.unhandledListener) {
997	      process.removeListener("unhandledRejection", state.unhandledListener);
998	      state.unhandledListener = null;
999	    }
1000	  }
1001	
1002	  function reportEventError(err: unknown): void {
1003	    sendEnvelope({
1004	      type: "event",
1005	      name: "error",
1006	      sessionId: state.sessionId,
1007	      detail: errMessage(err),
1008	      timestamp: Date.now(),
1009	    });
1010	  }
1011	
1012	  /**
1013	   * Notify the user via ctx.ui.notify if possible; otherwise fall back to
1014	   * stderr. The captured ctx from `session_start` can become stale across
1015	   * async boundaries (pi marks it stale on internal session replacement),
1016	   * so we never let a notify call crash the verifier — the message is more
1017	   * important than the channel.
1018	   */
1019	  function safeNotify(
1020	    ctx: ExtensionContext | ExtensionCommandContext,
1021	    message: string,
1022	    level: "info" | "warning" | "error",
1023	  ): void {
1024	    try {
1025	      ctx.ui.notify(message, level);
1026	    } catch {
1027	      const prefix = level === "error" ? "ERROR" : level === "warning" ? "WARN" : "INFO";
1028	      process.stderr.write(`[${prefix}] ${message}\n`);
1029	    }
1030	  }
1031	
1032	  // ─── Internal: low-level send ─────────────────────────────────────────
1033	
1034	  function sendEnvelope(envelope: Envelope): void {
1035	    const conn = state.verifierConn;
1036	    if (!conn || conn.destroyed) return;
1037	    try {
1038	      assertDirection(envelope, "builder-to-verifier");
1039	    } catch {
1040	      // Programming error — silently drop rather than crash the builder.
1041	      return;
1042	    }
1043	    try {
1044	      conn.write(encodeEnvelope(envelope));
1045	    } catch {
1046	      // ignore — close handler will clean up
1047	    }
1048	  }
1049	
1050	  // ─── Internal: footer rendering ───────────────────────────────────────
1051	
1052	  /**
1053	   * Update the verifier-connection phase. Was named `setFooter` historically
1054	   * because it used to ALSO install a bottom-of-screen custom footer that
1055	   * showed the same info. The footer was redundant once the input-bar
1056	   * border embedding (BuilderInputEditor) started rendering model / ctx %
1057	   * / verifier-state on the editor's borders directly — we dropped the
1058	   * footer install to avoid the duplicate display.
1059	   *
1060	   * The editor's `render()` reads `state.phase` on every TUI tick, so a
1061	   * bare state mutation is enough to trigger the visual refresh — we don't
1062	   * need to nudge pi explicitly.
1063	   */
1064	  function setFooter(
1065	    _ctx: ExtensionContext,
1066	    label: ConnectionPhase,
1067	  ): void {
1068	    state.phase = label;
1069	    // Nudge pi to re-render so the input-bar border picks up the new phase
1070	    // immediately. Without this, the border keeps showing the prior phase
1071	    // (e.g. `spawning`) until the user types something.
1072	    state.requestRender?.();
1073	  }
1074	
1075	  /**
1076	   * Return the current line count of the builder's session JSONL file.
1077	   * 0 if the file doesn't exist yet (pi creates it on first write — for the
1078	   * very first turn, before_agent_start may fire before the file exists).
1079	   * Errors propagate as 0 rather than throwing — losing the line offset is
1080	   * preferable to crashing the lifecycle event handler. The verifier
1081	   * tolerates 0 by falling back to a full-file read.
1082	   *
1083	   * For typical session sizes (KB-MB) this is negligible cost; for sessions
1084	   * that grow into hundreds of MB, consider a streaming line counter or
1085	   * caching the last-known count and counting only NEW bytes.
1086	   */
1087	  async function currentSessionFileLineCount(sessionPath: string): Promise<number> {
1088	    if (!sessionPath) return 0;
1089	    try {
1090	      const buf = await fs.readFile(sessionPath);
1091	      // Count `\n` bytes. JSONL entries always end with a newline (pi
1092	      // appends one), so this gives us the number of complete lines.
1093	      let count = 0;
1094	      for (let i = 0; i < buf.length; i++) {
1095	        if (buf[i] === 0x0a /* \n */) count++;
1096	      }
1097	      return count;
1098	    } catch {
1099	      return 0;
1100	    }
1101	  }
1102	
1103	  function errMessage(value: unknown): string {
1104	    if (value instanceof Error) return value.message;
1105	    if (typeof value === "string") return value;
1106	    try {
1107	      return JSON.stringify(value);
1108	    } catch {
1109	      return String(value);
1110	    }
1111	  }
1112	}
1113

