1	/**
2	 * Shared IPC envelope types + JSONL framing for the Pi Verifier Agent.
3	 *
4	 * Wire protocol — JSONL, one JSON object per line, terminated by `\n`.
5	 *
6	 * IMPORTANT — DO NOT use Node's `readline` module to consume these frames.
7	 * `readline` splits on the Unicode line separators U+2028 (LINE SEPARATOR)
8	 * and U+2029 (PARAGRAPH SEPARATOR) in addition to `\n`. Both code points
9	 * are valid characters inside JSON strings (JSON.parse will accept them
10	 * literally), so `readline`-based framing silently corrupts any envelope
11	 * whose payload — for example, a builder report containing source code,
12	 * UTF-8 prose, or pasted text — happens to include one of those code
13	 * points. We split on the byte `0x0A` (`\n`) ONLY. Period.
14	 *
15	 * Direction matrix (architecturally enforced — see assertDirection):
16	 *
17	 *   verifier ──► builder           builder ──► verifier
18	 *   ─────────────────────          ──────────────────────
19	 *   hello                          hello_ack
20	 *   prompt   (correction text)     prompt_ack
21	 *   report   (for inline render)   (no reply needed)
22	 *                                  event       ← unified lifecycle channel
23	 *
24	 *   Bidirectional (allowed on either side):
25	 *     ping / pong  — both verifier and builder run 10s liveness intervals.
26	 *     bye          — either side may close the channel cleanly.
27	 *
28	 * Round-trip examples (all of these survive JSON.stringify → \n-split → JSON.parse):
29	 *
30	 *   {"type":"hello","role":"verifier","sessionId":"a1b2","pid":4242}
31	 *   {"type":"event","name":"stop","sessionId":"a1b2","turnIndex":3,"timestamp":1714312800000}
32	 *   {"type":"prompt","sessionId":"a1b2","message":"Add NOT NULL to email","correlationId":"c-1"}
33	 *   {"type":"report","sessionId":"a1b2","turnIndex":3,"status":"verified",
34	 *    "summary":"schema ok","sections":{"verified":"- users: PASS"},"raw":"## Report\n..."}
35	 *   {"type":"event","name":"error","sessionId":"a1b2","detail":"tool execute failed",
36	 *    "timestamp":1714312800123}
37	 *
38	 *   Embedded special characters that must NOT corrupt the frame:
39	 *     - escaped newline inside a string  → "line1\nline2"  (JSON-escaped, no real \n byte on the wire)
40	 *     - U+2028 / U+2029 inside a string  → emitted as the literal 3-byte UTF-8 sequence
41	 *       (E2 80 A8 / E2 80 A9). `readline` would split on these; we don't.
42	 *     - quote characters                 → escaped as \" by JSON.stringify
43	 *     - embedded null                    → escaped as �
44	 *     - multi-megabyte payloads          → fine; we buffer until \n is seen
45	 */
46	
47	import type { Readable } from "node:stream";
48	
49	// ─── Envelope types ──────────────────────────────────────────────────────────
50	
51	export interface Hello {
52	  type: "hello";
53	  role: "verifier" | "verifiable";
54	  sessionId: string;
55	  pid: number;
56	}
57	
58	export interface HelloAck {
59	  type: "hello_ack";
60	  sessionId: string;
61	}
62	
63	export interface Prompt {
64	  type: "prompt";
65	  sessionId: string;
66	  message: string;
67	  deliverAs?: "followUp" | "steer";
68	  correlationId: string;
69	}
70	
71	export interface PromptAck {
72	  type: "prompt_ack";
73	  sessionId: string;
74	  correlationId: string;
75	  ok: boolean;
76	  error?: string;
77	}
78	
79	/**
80	 * Confidence ladder, highest → lowest. Drives the verifier's status-bar color
81	 * (green / orange / red) and is parsed from the verifier's `CONFIDENCE:` line.
82	 *
83	 *   PERFECT  — every claim verified, no gaps, no feedback           (green)
84	 *   VERIFIED — all checked passed, minor non-blocking gaps allowed   (green)
85	 *   PARTIAL  — no failures but significant unverifiable gaps         (orange)
86	 *   FEEDBACK — verifier_prompt fired; builder will correct           (orange)
87	 *   FAILED   — could not verify at all; escalating to human          (red)
88	 *
89	 * Note: FAILED here means "the verifier itself was unable to do its job"
90	 * (no oracle, no fixture, ambiguous claims), NOT "the work failed
91	 * verification." Work-failed-with-feedback is FEEDBACK — that's the system
92	 * working as designed; the loop closes and the builder fixes it.
93	 */
94	export type Confidence = "perfect" | "verified" | "partial" | "feedback" | "failed";
95	
96	export interface Report {
97	  type: "report";
98	  sessionId: string;
99	  turnIndex: number;
100	  status: "verified" | "failed" | "unsure";
101	  /** Per-cycle confidence grade — see Confidence type docs. */
102	  confidence: Confidence;
103	  summary: string;
104	  sections: Record<string, string>;
105	  raw: string;
106	}
107	
108	export interface Event {
109	  type: "event";
110	  name: "start" | "stop" | "error";
111	  sessionId: string;
112	  /** Monotonic counter — present for start / stop. NOT a JSONL row index. */
113	  turnIndex?: number;
114	  /** present for error events */
115	  detail?: string;
116	  timestamp: number;
117	  /**
118	   * The original user prompt that triggered this turn. Captured in the
119	   * builder's `input` event handler for non-extension-source inputs.
120	   * Present on `start` and `stop` events for the same turn so the verifier
121	   * can reference it without parsing the session JSONL. Omitted on error.
122	   */
123	  userPrompt?: string;
124	  /**
125	   * Line number in the builder's session JSONL where this turn's content
