1	/**
2	 * Socket-path resolution for the Pi Verifier Agent.
3	 *
4	 * Layout:
5	 *   actual socket : /tmp/pi-verifier/<sessionId>.sock
6	 *   breadcrumb    : <cwd>/.pi/state/verifier-<sessionId>.sock.ref   (plain text → socket path)
7	 *
8	 * Why `/tmp/pi-verifier/`:
9	 *   macOS limits `sun_path` (the Unix-domain-socket file path inside
10	 *   `struct sockaddr_un`) to 104 bytes. A path under the project root
11	 *   (e.g. `/Users/foo/Documents/projects/the-verifier-agent/.pi/state/verifier-<sid>.sock`)
12	 *   blows past 104 bytes for almost every realistic project location.
13	 *   `/tmp/pi-verifier/<sid>.sock` is short and predictable.
14	 *
15	 * The breadcrumb file in the project lets `ls .pi/state/` describe what
16	 * verifier sessions are running, and lets the verifier child resolve the
17	 * socket path by `--builder-session <sessionId>` alone.
18	 *
19	 * Permissions:
20	 *   `/tmp/pi-verifier` is created with mode 0700 — only the owning UID
21	 *   can connect to sockets inside it. That is our authentication.
22	 *
23	 * Cleanup:
24	 *   `cleanup()` swallows `ENOENT` so it's safe to call from
25	 *   `session_shutdown` regardless of whether the socket was ever bound
26	 *   or the breadcrumb ever written.
27	 */
28	
29	import { promises as fs } from "node:fs";
30	import * as path from "node:path";
31	
32	const SOCKET_DIR = "/tmp/pi-verifier";
33	const SOCKET_DIR_MODE = 0o700;
34	
35	/**
36	 * Headroom under macOS's 104-byte `sun_path` limit. We pick 100 to leave
37	 * a few bytes for safety (`sun_len`, terminator, future suffix).
38	 */
39	const SOCKET_PATH_MAX = 100;
40	
41	export interface ResolvedSocketPaths {
42	  socketPath: string;
43	  refPath: string;
44	}
45	
46	/**
47	 * Pure resolver — returns the canonical paths without touching disk.
48	 *
49	 * Throws if `socketPath` would exceed the macOS `sun_path` budget.
50	 * That's a programming error (caller passed an unexpectedly long
51	 * sessionId); the upstream callers should keep sessionIds short.
52	 */
53	export function resolveSocketPath(sessionId: string, cwd: string): ResolvedSocketPaths {
54	  if (!sessionId || /[\/\0\s]/.test(sessionId)) {
55	    throw new Error(
56	      `resolveSocketPath: sessionId must be non-empty and contain no path separators, ` +
57	        `null bytes, or whitespace. Got: ${JSON.stringify(sessionId)}.`,
58	    );
59	  }
60	  const socketPath = path.join(SOCKET_DIR, `${sessionId}.sock`);
61	  if (socketPath.length > SOCKET_PATH_MAX) {
62	    throw new Error(
63	      `Resolved socket path is ${socketPath.length} bytes, which exceeds the safe ` +
64	        `${SOCKET_PATH_MAX}-byte budget under macOS's 104-byte sun_path limit. ` +
65	        `sessionId="${sessionId}" yielded path="${socketPath}". Use a shorter sessionId.`,
66	    );
67	  }
68	  const refPath = path.join(cwd, ".pi", "state", `verifier-${sessionId}.sock.ref`);
69	  return { socketPath, refPath };
70	}
71	
72	/**
73	 * Ensure `/tmp/pi-verifier` exists and is mode 0700.
74	 *
75	 * Idempotent — safe to call on every session_start. The chmod is
76	 * unconditional so a stale dir created with looser perms by an older
77	 * version is tightened on the next run.
78	 */
79	export async function ensureSocketDir(): Promise<void> {
80	  await fs.mkdir(SOCKET_DIR, { recursive: true });
81	  await fs.chmod(SOCKET_DIR, SOCKET_DIR_MODE);
82	}
83	
84	/**
85	 * Write the breadcrumb file pointing at the actual socket.
86	 *
87	 * Creates the `.pi/state/` parent dir if needed (so callers don't need
88	 * a separate ensureProjectState step). Content is the plain socket path
89	 * with a trailing newline so `cat` output is human-friendly.
90	 */
